    detail::OperatorHandle m_handle;
};

inline __OPNAME__::__OPNAME__()
{
    NVCVOperatorHandle h = nullptr;
    nvcv::detail::CheckThrow(cvcuda__OPNAME__Create(&h));
    assert(h);
    m_handle = detail::OperatorHandle{h};
